void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 center1 = vec2(sin(iTime), cos(iTime))*.2;
    vec2 center2 = vec2(sin(.4*iTime), cos(iTime*.1))*1.2;
    vec2 center3 = vec2(sin(.2*iTime), cos(iTime*.2))*.3;



    vec2 st = ((fragCoord/iResolution.xy) - vec2(.5)) * 2.;

    float v1 = mod(length(st - center1) - iTime, .7)*10.;
    float v2 = mod(length(st - center2) - iTime, .7)*10.;
    float v3 = mod(length(st - center3) - iTime, .4)*10.;



    fragColor= vec4(max(v1,v2)*.2,max(v2,v3)*2.,max(v3,v1)*.4,1.);
}
